package com.wildalert.detectionhistory.history

import java.time.Instant
import java.util.UUID

/**
 * One recognised animal, as this service stores and serves it.
 *
 * Hand-written rather than generated by jOOQ (codegen has pojos=false): the stored row and the
 * domain type drift apart as soon as there is a column the API should not expose, and a generated
 * POJO would put that decision in a build file.
 *
 * [recipient] is the hunter's inbound address, already normalised (trimmed, lower-cased). Null
 * only for a legacy event that carried just a [hunterId] — see the migration.
 */
data class Detection(
    val sourceEventId: UUID,
    val recipient: String?,
    val hunterId: UUID?,
    val storageKey: String,
    val species: String,
    val confidence: Double,
    val lowConfidence: Boolean,
    val occurredAt: Instant,
)

/**
 * One species in a hunter's summary: how often it showed up, when it was last seen, and how
 * confident the classifier was on average.
 *
 * This is the shape that justifies jOOQ in this service — an aggregate over a filtered range,
 * which as JPA entities would be either an N+1 or a native query string with no type checking.
 */
data class SpeciesSummary(
    val species: String,
    val sightings: Int,
    val lastSeenAt: Instant,
    val averageConfidence: Double,
)
